example:
// shop/billing.bynk
context shop.billing

actor Admin = Caller where IsContext(shop.admin)

service refunds {
  on call(id: String) -> Effect[Int] by Admin {
    Effect.pure(1)
  }
}

service quote {
  on call(id: String) -> Effect[Int] by Caller {
    Effect.pure(2)
  }
}

// shop/orders.bynk
context shop.orders

consumes shop.billing

service place {
  on call(id: String) -> Effect[Int] by Caller {
    shop.billing.refunds(id)   // ✗ `shop.orders` is not `shop.admin`
    shop.billing.quote(id)   // ✓ `quote` admits any consuming context
  }
}
